-- composition of rule kernels L:scalar_subquery_to_join x L:simplify_expressions (datafusion), template exists
SELECT count(*) FROM (SELECT '_'::text AS c0, '2000-01-01'::date AS c1) AS ka WHERE EXISTS (SELECT 1 FROM (WITH cte1 AS (SELECT 500 AS c0) SELECT FALSE AS c0, a1.c1 AS c1 FROM tp AS a1 WHERE CASE WHEN ((SELECT MAX ('1999-12-31'::date) FROM cte1 AS a2 WHERE LEAST ((a1.c0 IS NULL), TRUE)) IN (SELECT '1970-01-01'::date AS c0)) THEN FALSE ELSE TRUE END) AS kb);
-- pgfuzz:check kernel:exists SELECT CASE WHEN (SELECT count(*) FROM (WITH cte1 AS (SELECT 500 AS c0) SELECT FALSE AS c0, a1.c1 AS c1 FROM tp AS a1 WHERE CASE WHEN ((SELECT MAX ('1999-12-31'::date) FROM cte1 AS a2 WHERE LEAST ((a1.c0 IS NULL), TRUE)) IN (SELECT '1970-01-01'::date AS c0)) THEN FALSE ELSE TRUE END) AS kb) > 0 THEN (SELECT count(*) FROM (SELECT '_'::text AS c0, '2000-01-01'::date AS c1) AS ka) ELSE 0 END
